/* FRANK'S COMPUTER — sampled UI sounds.
   Windows XP sound pack supplied by the client (assets_src/xpsounds/*.wav),
   encoded to 128k MP3 at build time of this file. Upgrades FR.sound.play(name) to play these samples through Web Audio,
   decoded lazily (after the first user gesture or on first play). Falls back to the synthesised SEQ tones in
   core.js when a name is unknown, Web Audio is missing, or decoding fails. */
(() => {
  FR.data = FR.data || { texts: {} };
  FR.data.sounds = {
    startup: 'data:audio/mpeg;base64,',
    logon: 'data:audio/mpeg;base64,',
    logoff: 'data:audio/mpeg;base64,',
    shutdown: 'data:audio/mpeg;base64,',
    error: 'data:audio/mpeg;base64,',
    exclamation: 'data:audio/mpeg;base64,',
    ding: 'data:audio/mpeg;base64,',
    default: 'data:audio/mpeg;base64,',
    notify: 'data:audio/mpeg;base64,',
    mail: 'data:audio/mpeg;base64,',
    click: 'data:audio/mpeg;base64,',
    start: 'data:audio/mpeg;base64,',
    nav: 'data:audio/mpeg;base64,',
    recycle: 'data:audio/mpeg;base64,',
    minimize: 'data:audio/mpeg;base64,',
    maximize: 'data:audio/mpeg;base64,',
    restore: 'data:audio/mpeg;base64,',
    tada: 'data:audio/mpeg;base64,',
    unlock: 'data:audio/mpeg;base64,',
    popup: 'data:audio/mpeg;base64,',
  };

  // game-facing names -> sample names
  const ALIAS = { chord: 'exclamation', warn: 'exclamation', critical: 'error', balloon: 'notify', navigate: 'nav', welcome: 'logon' };
  const synth = FR.sound.play;              // original synthesised player (core.js)
  const buffers = {}, pending = {}, broken = {};
  const active = new Set();
  let ctx = null, master = null, warmed = false;

  const getCtx = () => {
    if (ctx) return ctx;
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return null;
    try { ctx = new AC(); master = ctx.createGain(); master.gain.value = FR.sound.volume; master.connect(ctx.destination); } catch (e) { ctx = null; }
    return ctx;
  };
  const toBuffer = uri => {
    const bin = atob(uri.slice(uri.indexOf(',') + 1)), u = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) u[i] = bin.charCodeAt(i);
    return u.buffer;
  };
  const keyOf = n => (ALIAS[n] || n);

  // decode one sample once; resolves to an AudioBuffer
  function decode(name) {
    const k = keyOf(name);
    if (buffers[k]) return Promise.resolve(buffers[k]);
    if (pending[k]) return pending[k];
    const c = getCtx(), uri = FR.data.sounds[k];
    if (!c || !uri || broken[k]) return Promise.reject(new Error('no sample: ' + name));
    pending[k] = new Promise((res, rej) => {
      const ok = b => { buffers[k] = b; res(b); };
      const bad = e => { broken[k] = true; delete pending[k]; rej(e || new Error('decode failed: ' + k)); };
      try {
        const p = c.decodeAudioData(toBuffer(uri), ok, bad);   // callback form for old Safari, promise for the rest
        if (p && p.then) p.then(ok, bad);
      } catch (e) { bad(e); }
    });
    return pending[k];
  }

  function startBuffer(b) {
    if (FR.sound.muted || !ctx) return;
    const s = ctx.createBufferSource();
    s.buffer = b; s.connect(master);
    active.add(s); s.onended = () => active.delete(s);
    s.start();
  }

  function warm() {
    if (warmed) return; warmed = true;
    const c = getCtx(); if (!c) return;
    if (c.state === 'suspended') c.resume().catch(() => {});
    Object.keys(FR.data.sounds).forEach(k => decode(k).catch(() => {}));
  }
  ['pointerdown', 'keydown', 'touchstart'].forEach(ev => window.addEventListener(ev, function once() {
    window.removeEventListener(ev, once, true); warm();
  }, true));

  let muted = !!FR.sound.muted;
  Object.defineProperty(FR.sound, 'muted', {
    configurable: true, enumerable: true,
    get: () => muted,
    set: v => { muted = !!v; if (muted) active.forEach(s => { try { s.stop(); } catch (e) {} }), active.clear(); },
  });
  FR.sound.volume = 1;
  FR.sound.setVolume = v => { FR.sound.volume = Math.max(0, Math.min(1, +v || 0)); if (master) master.gain.value = FR.sound.volume; };
  FR.sound.names = Object.keys(FR.data.sounds).concat(Object.keys(ALIAS));
  FR.sound.decode = decode;                  // FR.sound.decode('tada').then(buf => buf.duration)
  FR.sound.synth = n => synth.call(FR.sound, n);

  FR.sound.play = function (n) {
    if (FR.sound.muted) return;
    const k = keyOf(n);
    if (!FR.data.sounds[k] || broken[k]) return synth.call(FR.sound, n);
    const c = getCtx();
    if (!c) return synth.call(FR.sound, n);
    const t0 = Date.now(), fresh = () => Date.now() - t0 < 700;  // drop a sound that would arrive late
    const go = b => {
      if (c.state === 'running') return startBuffer(b);
      c.resume().then(() => { if (fresh()) startBuffer(b); }, () => {});
    };
    if (c.state === 'suspended') c.resume().catch(() => {});
    if (buffers[k]) return go(buffers[k]);
    decode(k).then(b => { if (fresh()) go(b); }, () => synth.call(FR.sound, n));
  };
})();
